<?php require 'config.php'; role(['admin','kasir']); $menus=$conn->query("SELECT m.*,c.name category FROM menus m JOIN categories c ON c.id=m.category_id WHERE m.stock>0 ORDER BY m.name");include 'partials/header.php';?><div class="d-flex justify-content-between align-items-end mb-3"><div><div class="section-title">Kasir / POS</div><div class="sub">Pilih menu untuk menambahkan ke keranjang.</div></div></div><div class="row g-3"><div class="col-lg-8"><div class="row g-3"><?php while($m=$menus->fetch_assoc()):?><div class="col-sm-6 col-xl-4"><div class="cardx product p-3 h-100" onclick='addItem(<?=json_encode(["id"=>(int)$m["id"],"name"=>$m["name"],"price"=>(int)$m["price"],"stock"=>(int)$m["stock"]])?>)'><div class="d-flex justify-content-between"><span class="badge-soft"><?=$m['category']?></span><small class="text-muted">Stok <?=$m['stock']?></small></div><b class="d-block mt-3"><?=htmlspecialchars($m['name'])?></b><span class="price d-block mt-2"><?=rupiah($m['price'])?></span></div></div><?php endwhile;?></div></div><div class="col-lg-4"><div class="cardx p-3 sticky-lg-top" style="top:95px"><h5 class="mb-1">Keranjang</h5><div class="sub">Pesanan pelanggan</div><div id="cart" class="mt-3"></div><hr><div class="d-flex justify-content-between"><b>Total</b><b id="total">Rp 0</b></div><input id="table" class="form-control mt-3" placeholder="Nomor meja"><select id="type" class="form-select mt-2"><option value="dine_in">Dine In</option><option value="takeaway">Take Away</option></select><select id="payment" class="form-select mt-2"><option value="cash">Tunai</option><option value="e_wallet">E-Wallet (simulasi)</option></select><input id="pay" type="number" class="form-control mt-2" placeholder="Nominal bayar"><button class="btn btn-primary w-100 mt-3" onclick="checkout()"><i class="bi bi-credit-card me-1"></i> Bayar & Cetak Struk</button></div></div></div><script>let cart=[];const rp=n=>'Rp '+n.toLocaleString('id-ID');function addItem(m){let x=cart.find(i=>i.id===m.id);if(x){if(x.qty<m.stock)x.qty++;}else cart.push({...m,qty:1});render()}function render(){document.getElementById('cart').innerHTML=cart.length?cart.map((i,n)=>`<div class="d-flex justify-content-between align-items-center py-2 border-bottom"><div><b>${i.name}</b><small class="d-block text-muted">${i.qty} x ${rp(i.price)}</small></div><div><b>${rp(i.price*i.qty)}</b> <button class="btn btn-sm text-danger" onclick="cart.splice(${n},1);render()"><i class="bi bi-x-circle"></i></button></div></div>`).join(''):'<div class="empty">Keranjang masih kosong</div>';document.getElementById('total').innerText=rp(cart.reduce((s,i)=>s+i.price*i.qty,0))}async function checkout(){let total=cart.reduce((s,i)=>s+i.price*i.qty,0),pay=+document.getElementById('pay').value;if(!cart.length)return alert('Keranjang kosong');if(pay<total)return alert('Pembayaran kurang');let f=new FormData();f.append('action','checkout');f.append('items',JSON.stringify(cart));f.append('table_number',document.getElementById('table').value);f.append('order_type',document.getElementById('type').value);f.append('payment_method',document.getElementById('payment').value);f.append('pay_amount',pay);let r=await fetch('checkout.php',{method:'POST',body:f});let d=await r.json();if(!d.success)return alert(d.message);location.href='receipt.php?id='+d.id}render();</script><?php include 'partials/footer.php';?>